function makeVideoBrowser(root,playlist){root.replaceChildren();let index=0;const node=(tag,text,cls)=>{const n=document.createElement(tag);if(text)n.textContent=text;if(cls)n.className=cls;return n};const stage=node('div',null,'video-frame video-browser-stage');const frame=node('iframe');frame.loading='lazy';frame.allow='accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share';frame.referrerPolicy='strict-origin-when-cross-origin';frame.allowFullscreen=true;stage.append(frame);const details=node('div',null,'slider-details');const title=node('h3'),count=node('span',null,'slider-count'),listName=node('p',playlist.title);details.append(title,listName,count);const controls=node('div',null,'video-browser-controls');const prev=node('button','← Previous video'),next=node('button','Next video →'),external=node('a','Watch on YouTube ↗','text-link');prev.type=next.type='button';external.target='_blank';external.rel='noopener';controls.append(prev,external,next);const strip=node('div',null,'slider-thumbs video-thumbs');strip.setAttribute('aria-label','Videos in '+playlist.title);
function select(n,user=false){index=(n+playlist.videos.length)%playlist.videos.length;const video=playlist.videos[index];frame.src='https://www.youtube-nocookie.com/embed/'+video.id+'?list='+playlist.id+'&rel=0'+(user?'&autoplay=1':'');frame.title=video.title;title.textContent=video.title;count.textContent=(index+1)+' / '+playlist.videos.length;external.href='https://www.youtube.com/watch?v='+video.id+'&list='+playlist.id;[...strip.children].forEach((b,i)=>{b.classList.toggle('selected',i===index);b.setAttribute('aria-pressed',String(i===index))});if(user){const b=strip.children[index];strip.scrollTo({left:b.offsetLeft-strip.offsetLeft-(strip.clientWidth-b.clientWidth)/2,behavior:'smooth'})}}
playlist.videos.forEach((video,i)=>{const b=node('button',null,'slider-thumb video-thumb');b.type='button';b.title=video.title;b.setAttribute('aria-label','Play '+video.title);const img=node('img');img.src=video.thumbnail;img.alt='';img.loading='lazy';const caption=node('span',video.title);b.append(img,caption);b.addEventListener('click',()=>select(i,true));strip.append(b)});prev.addEventListener('click',()=>select(index-1,true));next.addEventListener('click',()=>select(index+1,true));root.append(stage,details,controls,strip);select(0);}
fetch('playlist-catalogue.json').then(r=>{if(!r.ok)throw Error('Catalogue unavailable');return r.json()}).then(lists=>{document.querySelectorAll('[data-playlist-browser]').forEach(root=>{const list=lists.find(p=>p.id===root.dataset.playlistBrowser);if(list)makeVideoBrowser(root,list)});const picker=document.querySelector('.playlist-picker');if(picker){picker.replaceChildren();const root=document.getElementById('playlist-browser');lists.forEach(list=>{const b=document.createElement('button');b.textContent=list.title;b.type='button';b.addEventListener('click',()=>{picker.querySelectorAll('button').forEach(button=>{button.classList.toggle('active',button===b);button.setAttribute('aria-pressed',String(button===b))});makeVideoBrowser(root,list);document.getElementById('playlist-status').textContent=list.title+' · '+list.videos.length+' videos';document.getElementById('playlist-external').href='https://youtube.com/playlist?list='+list.id});picker.append(b)});picker.children[2].click()}}).catch(()=>document.querySelectorAll('[data-playlist-browser],#playlist-browser').forEach(root=>{root.textContent='Video list could not load. Please use the YouTube playlist link.'}));
